    assign w_test_bin[2] = PAD[16];
    assign w_test_bin[1] = PAD[18];
    assign w_test_bin[0] = PAD[20];

    chip_top i_chip (
        .PAD(PAD),
        .VDD(VDD),
        .VSS(VSS),
        .VDDPST(VDDPST),
        .VSSPST(VSSPST)
    );


    // Testbench ctrl
    reg f_tb_clk, f_tb_rst;
    wire w_tb_pass, w_tb_fail, w_tb_prog_done;

    // Logging
    reg [31:0] f_tb_verbosity, f_tb_max_cycle, f_tb_cycle_cnt;

    // -- Test ---------------------------------------------------------------
    // Signals
    wire w_test_clk;
    wire w_test_reset;
    wire w_test_start;
    wire [3:0] w_test_bcd1;
    wire [3:0] w_test_bcd0;
    wire w_test_ready;
    wire w_test_done_tick;
    wire [6:0] w_test_bin;

    // Tester
    basic i_tester (
        .tb_clk(f_tb_clk)
        ,.tb_rst(f_tb_rst)
        ,.tb_pass(w_tb_pass)
        ,.tb_fail(w_tb_fail)
        ,.tb_prog_done(w_tb_prog_done)
        ,.tb_verbosity(f_tb_verbosity)
        ,.tb_cycle_cnt(f_tb_cycle_cnt)
        ,.clk(w_test_clk)
        ,.reset(w_test_reset)
        ,.start(w_test_start)
        ,.bcd1(w_test_bcd1)
        ,.bcd0(w_test_bcd0)
        ,.ready(w_test_ready)
